import java.nio.file.*;
import java.util.*;
import org.apache.maven.model.*;
import org.apache.maven.model.building.*;
import org.apache.maven.model.resolution.*;
public final class ReadPomLicenses {
 static final class CachedResolver implements ModelResolver {
  final Path root;
  CachedResolver(Path root){this.root=root;}
  public ModelSource resolveModel(String g,String a,String v) throws UnresolvableModelException {
   var p=root.resolve(g.replace('.','/')).resolve(a).resolve(v).resolve(a+"-"+v+".pom");
   if(!Files.isRegularFile(p)) throw new UnresolvableModelException("Uncached parent/BOM",g,a,v);
   System.err.println("MODEL_SOURCE\t"+p);
   return new FileModelSource(p.toFile());
  }
  public ModelSource resolveModel(Parent p)throws UnresolvableModelException{return resolveModel(p.getGroupId(),p.getArtifactId(),p.getVersion());}
  public ModelSource resolveModel(Dependency p)throws UnresolvableModelException{return resolveModel(p.getGroupId(),p.getArtifactId(),p.getVersion());}
  public void addRepository(Repository r){}
  public void addRepository(Repository r,boolean replace){}
  public ModelResolver newCopy(){return new CachedResolver(root);}
 }
 public static void main(String[] args)throws Exception {
  var builder=new DefaultModelBuilderFactory().newInstance();
  for(var line:Files.readAllLines(Path.of(args[1]))) {
   var request=new DefaultModelBuildingRequest().setPomFile(Path.of(line).toFile()).setSystemProperties(System.getProperties()).setProcessPlugins(false).setModelResolver(new CachedResolver(Path.of(args[0])));
   var model=builder.build(request).getEffectiveModel();
   if(model.getLicenses().isEmpty())throw new AssertionError("No license metadata: "+line);
   for(var license:model.getLicenses())System.out.println(model.getGroupId()+":"+model.getArtifactId()+":"+model.getVersion()+"\t"+license.getName()+"\t"+license.getUrl());
  }
 }
}
